def test_roundtrip_json_invocationusage():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "inputTokens": 150,
      "outputTokens": 42,
      "totalTokens": 192
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = InvocationUsage.load(original_data)
    saved_data = instance.save()
    reloaded = InvocationUsage.load(saved_data)
    assert reloaded is not None
    assert reloaded.input_tokens == 150
    assert reloaded.output_tokens == 42
    assert reloaded.total_tokens == 192


